from typing import List

def count_up_to(n: int) -> List[int]:
    if n <= 2:
        return []

    primes = []

    for num in range(2, n):
        is_prime = True
        for divisor in range(2, int(num ** 0.5) + 1):
            if num % divisor == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return primes
